use super::*;

fn table(items:&[Value])->String{
    let mut out=String::from("<div class=table-scroll><table class=materials-table><thead><tr><th>Material / specification</th><th>Net quantity</th><th>Order quantity</th><th>Retail unit price</th><th>Selected total</th></tr></thead><tbody>");
    for i in items{out.push_str(&format!(r#"<tr><td><strong>{}</strong><details><summary>{} · Quantity &amp; price basis</summary><p>{}</p><p>{} · {}. {}</p></details></td><td data-label="Net quantity">{}<small>{}</small></td><td data-label="Order quantity">{}<small>{}</small></td><td data-label="Retail unit price"><div class=price-input><span>$</span><input type=number min=0 step=.01 max=100000 data-price="{}" aria-label="Retail unit price {}" value="{}"></div><small>Selected ${}/{} · {}% discount</small></td><td data-label="Selected line total">{}</td></tr>"#,
        esc(s(i,"name")),esc(s(i,"status")),esc(s(i,"basis")),esc(s(&i["priceReference"],"status")),esc(s(i,"discountBasis")),esc(s(&i["priceReference"],"note")),n(i,"net"),esc(s(i,"unit")),n(i,"qty"),esc(s(i,"unit")),esc(s(i,"id")),esc(s(i,"name")),n(i,"retailPrice"),n(i,"price"),esc(s(i,"unit")),n(i,"discountPercent"),money(n(i,"total"))));}
    out.push_str("</tbody></table></div>");out
}

pub fn render(a:&State)->String{
    let m=&a.m;let c=&a.c;let edited=n(m,"budgetOverrideCount")>0.;
    let mut out=format!(r#"<div class=estimate-heading><div><p class=kicker>MATERIALS / LIVE TAKEOFF</p><h2>Materials &amp; budget</h2><p>Expand a category for quantities and calculated costs. Type beside it to set your own category budget.</p></div><div class=cost-totals><div class=total-card><span>{}</span><strong>{}</strong><small>USD · {}% material tax · {}</small></div><div class=project-cost-total><span>Labor + land + permits + survey</span><strong>{}</strong><small>Separate from materials</small></div></div></div>"#,
        if edited{"Materials budget · edited"}else{"Materials total"},money(n(m,"materialsBudgetTotal")),c.tax,if edited{"category budget edits applied"}else{"calculated itemized costs"},money(n(m,"projectCostTotal")));
    out.push_str(&format!(r#"<div class=quantity-summary><div><b>{} stud pieces</b><span>{} exterior / gable · {} interior · {}</span></div><div><b>{} drywall sheets</b><span>4 × 16 ft · {}% ordering waste</span></div><div><b>{} I-joist rafters</b><span>Roof and dormer members · sizing pending</span></div></div>"#,n(&m["counts"],"studs"),n(&m["counts"],"exteriorStuds"),n(&m["counts"],"interiorStuds"),esc(&c.stud_type),n(&m["counts"],"drywallSheets"),c.waste,n(&m["counts"],"rafters")));
    out.push_str(r#"<div class=estimate-toolbar><div class=pricing-switch role=group aria-label="Material pricing">"#);
    for(mode,label)in[("Retail","Retail"),("Wholesale estimate","Wholesale / bulk estimate")]{out.push_str(&format!(r#"<button data-action=pricing-mode data-value="{}" class="button {}" aria-pressed="{}">{}</button>"#,mode,if c.pricing_mode==mode{"primary"}else{"secondary"},c.pricing_mode==mode,label));}
    out.push_str("</div>");out.push_str(&btn("csv","Export estimate","secondary"));out.push_str("</div>");
    out.push_str(&format!(r#"<details class=pricing-note data-cost-group=pricing><summary>Price sources &amp; discount assumptions</summary><p>Reference retail prices reviewed {}. {} lines still require a product-specific supplier quote. ZIP {} locates the project; this site does not fetch live store prices.</p><p>Bulk mode uses published quantity tiers where available. Otherwise each category uses an editable whole-house volume scenario: 25% off retail for categories of $10,000 or more, 20% from $2,000 and 10% below, in line with the 20–30% builders typically get on a full-house package. Enter your actual quote to replace it. This is not a guaranteed wholesale quote or every possible discount. Discount programs are not stacked.</p><p>Retail comparison subtotal: {} · Selected-price savings: {}.</p>"#,pricing::PRICE_DATE,n(&m["pricing"],"unquotedLineCount"),if c.zip.is_empty(){"not selected"}else{&c.zip},money(n(m,"retailSubtotal")),money(n(m,"volumeSavings"))));
    for source in m["pricing"]["sources"].as_array().unwrap(){out.push_str(&format!("<a href=\"{}\" target=_blank rel=\"noopener noreferrer\">{}</a>",esc(s(source,"url")),esc(s(source,"name"))));}out.push_str("</details><div class=category-list>");
    for group in m["categoryBudgets"].as_array().unwrap(){let cat=s(group,"name");let override_on=group["overridden"]==true;
        out.push_str(&format!(r#"<section class="cost-category {}"><div class=category-row><details class=category-detail data-cost-group="{}"><summary><span>{}</span><small>{}</small></summary><div class=category-body><div class=category-calculated><span>Calculated itemized total</span><strong>{}</strong><small>Retail reference: {}</small></div>"#,if override_on{"budget-edited"}else{""},esc(cat),esc(cat),if override_on{"Budget edited"}else{"Calculated total"},money(n(group,"calculated")),money(n(group,"retail"))));
        if c.pricing_mode!="Retail"{out.push_str(&format!(r#"<label class="field category-discount">Supplier / scenario discount · %<input type=number min=0 max=80 step=.01 data-discount="{}" aria-label="{} supplier discount percent" value="{}"></label><p class=muted>Use your quoted discount. A category discount replaces published item tiers.</p>"#,esc(cat),esc(cat),n(group,"discountPercent")));}
        let items=m["items"].as_array().unwrap().iter().filter(|i|s(i,"category")==cat).cloned().collect::<Vec<_>>();out.push_str(&table(&items));out.push_str("</div></details>");
        out.push_str(&format!(r#"<div class=category-budget><label><span>{}</span><div class=price-input><span>$</span><input type=number min=0 max=1000000000 step=.01 data-budget="{}" aria-label="{} category budget" value="{}"></div></label><button class=budget-reset data-action=budget-reset data-value="{}" aria-label="Use calculated {} total" {}>Reset</button></div></div></section>"#,if override_on{"Your budget"}else{"Category total"},esc(cat),esc(cat),n(group,"budget"),esc(cat),esc(cat),if override_on{""}else{"disabled"}));
    }
    out.push_str("</div><details class=project-allowances data-cost-group=project><summary>Labor, land, permits &amp; survey <strong>");out.push_str(&money(n(m,"projectCostTotal")));out.push_str("</strong></summary><div class=project-allowance-fields>");
    for cost in m["projectCosts"].as_array().unwrap(){out.push_str(&field_num(s(cost,"id"),&format!("{} · $",s(cost,"name")),n(cost,"amount"),0.,1e9));}out.push_str("</div><p class=muted>Listed individually here and in Materials. Added once to the combined budget; no material waste or sales tax.</p></details>");
    out.push_str("<details class=takeoff-settings data-cost-group=settings><summary>Waste, tax &amp; framing details</summary><div class=two-fields>");out.push_str(&field_num("waste","Ordering waste · %",c.waste,0.,30.));out.push_str(&field_num("tax","Material sales tax · %",c.tax,0.,20.));out.push_str("</div><div class=role-grid>");for(role,count)in m["piecesByRole"].as_object().unwrap(){out.push_str(&format!("<div><strong>{}</strong><span>{}</span></div>",count,esc(role)));}out.push_str("</div>");out.push_str(&profile_html(a));out.push_str("</details>");
    out.push_str(&structural_html(a));
    out.push_str(&format!(r#"<div class=estimate-footer><p>Quantities describe the design model. Retail rates and unquoted discounts are estimating allowances; freight, sitework, loose decor and engineering are excluded. Category budget edits change the budget only; quantities and calculated prices remain visible in each drop-down.</p><dl><div><dt>Calculated materials subtotal</dt><dd>{}</dd></div><div><dt>Budget materials subtotal</dt><dd>{}</dd></div><div><dt>Material budget tax</dt><dd>{}</dd></div><div><dt>Materials {}</dt><dd>{}</dd></div><div><dt>Labor + land + permits + survey</dt><dd>{}</dd></div><div><dt>Combined budget</dt><dd>{}</dd></div></dl></div>"#,money(n(m,"subtotal")),money(n(m,"budgetSubtotal")),money(n(m,"budgetTax")),if edited{"budget"}else{"total"},money(n(m,"materialsBudgetTotal")),money(n(m,"projectCostTotal")),money(n(m,"projectTotal"))));out
}
